<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, ArrowUpRight, BookOpen, Check, ChevronRight, Clock3, FileUp, Flame, Layers3, Lightbulb, Network, Play, Plus, Sparkles, Target, TrendingUp } from 'lucide-vue-next'
import ChartPanel from '../components/ChartPanel.vue'
import { studyApi } from '../api'
import { useStudyStore } from '../stores/study'
import type { Course, KnowledgeNode, StudyTask } from '../types'
import { profileState } from '../stores/profile'

const router = useRouter(); const store = useStudyStore()
const todayLabel = new Intl.DateTimeFormat('zh-CN',{weekday:'long',month:'long',day:'numeric',timeZone:'Asia/Shanghai'}).format(new Date())
const dashboardLoading = ref(true); const dashboardError = ref('')
const stats = ref({ hoursToday: '—' as string | number, mastered: 0, weeklyTasks: 0, streak: 0, weekHours: Array(7).fill(0), weekScores: Array<number | null>(7).fill(null) })
const courses = ref<Course[]>([]); const graphNodes = ref<KnowledgeNode[]>([]); const graphLinks = ref<Array<{source:string;target:string}>>([]); const quizHistory = ref<unknown[]>([]); const mistakes = ref<Array<{topic:string;wrong:number;mastered:boolean;course:string;nextReviewAt:string}>>([]); const tasks = computed(() => store.tasks.slice(0,3)); const uploadInput = ref<HTMLInputElement>()
const activeStudy = ref<{id:string;startedAt:string}|null>(null); const studyElapsed = ref(0); let studyTimer:number|undefined
const mistakeStats = ref({ mastered: 0, due: 0, upcoming: 0 })
const hasQuizHistory = computed(() => quizHistory.value.length > 0)
onMounted(async () => {
  try {
    const [dashboard, graph, records, attempts] = await Promise.all([studyApi.dashboard(), studyApi.graph('ds'), studyApi.mistakes(), studyApi.quizAttempts()])
    stats.value = dashboard; courses.value = dashboard.courses; graphNodes.value = graph.nodes; graphLinks.value = graph.links
    mistakes.value = records; quizHistory.value = attempts
    mistakeStats.value = { mastered: records.filter((item:any)=>item.mastered).length, due: records.filter((item:any)=>!item.mastered&&new Date(item.nextReviewAt)<=new Date()).length, upcoming: records.filter((item:any)=>!item.mastered&&new Date(item.nextReviewAt)>new Date()).length }
    await store.loadTasks()
    activeStudy.value = await studyApi.activeStudySession()
    if (activeStudy.value) studyElapsed.value = Math.max(0, Math.floor((Date.now()-new Date(activeStudy.value.startedAt).getTime())/1000))
    if (activeStudy.value) studyTimer=window.setInterval(()=>{studyElapsed.value=Math.max(0,Math.floor((Date.now()-new Date(activeStudy.value!.startedAt).getTime())/1000))},1000)
  } catch (error) { console.error('学习总览加载失败', error); dashboardError.value = error instanceof Error ? error.message : '学习数据暂时无法加载，请检查网络后重试。' }
  finally { dashboardLoading.value = false }
})
onBeforeUnmount(()=>window.clearInterval(studyTimer))
const studyClock = computed(()=>`${String(Math.floor(studyElapsed.value/3600)).padStart(2,'0')}:${String(Math.floor(studyElapsed.value%3600/60)).padStart(2,'0')}:${String(studyElapsed.value%60).padStart(2,'0')}`)
async function toggleStudyTimer(){
  try{
    if(activeStudy.value){await studyApi.finishStudySession(activeStudy.value.id);activeStudy.value=null;studyElapsed.value=0;window.clearInterval(studyTimer);stats.value=await studyApi.dashboard()}
    else{activeStudy.value=await studyApi.startStudySession(courses.value[0]?.id);studyElapsed.value=0;studyTimer=window.setInterval(()=>{studyElapsed.value++},1000)}
  }catch(error){console.error('学习计时操作失败',error)}
}
const learningOption = computed(() => ({ grid: { left: 8, right: 12, top: 18, bottom: 26, containLabel: true }, xAxis: { type: 'category' as const, boundaryGap: false, data: ['周一','周二','周三','周四','周五','周六','周日'], axisLine: { show: false }, axisTick: { show: false }, axisLabel: { color: '#9290a0', fontSize: 13, margin: 14 } }, yAxis: { type: 'value' as const, min: 0, max: 100, interval: 20, splitLine: { lineStyle: { color: '#eeedf2', type: 'dashed' as const } }, axisLabel: { color: '#aaa8b5', fontSize: 12, formatter: '{value}%'  } }, tooltip: { trigger: 'axis' as const, backgroundColor: '#282438', borderWidth: 0, textStyle: { color: '#fff' }, formatter: (p: unknown) => { const x = (p as Array<{axisValue:string;data:number}>)[0]; return `${x.axisValue}<br/><b>${x.data}%</b>` } }, series: [{ type: 'line' as const, smooth: true, data: stats.value.weekScores, symbol: 'circle', symbolSize: 7, lineStyle: { color: '#7958df', width: 3 }, itemStyle: { color: '#7958df', borderWidth: 2, borderColor: '#fff' }, areaStyle: { color: { type: 'linear' as const, x: 0, y: 0, x2: 0, y2: 1, colorStops: [{ offset: 0, color: 'rgba(125,91,223,.2)' },{ offset: 1, color: 'rgba(125,91,223,0)' }] } } }] }))
const masteryOption = computed(() => ({ tooltip: { trigger: 'item' as const }, legend: { bottom: 0, itemWidth: 7, itemHeight: 7, textStyle: { color: '#777486', fontSize: 12 } }, series: [{ type: 'pie' as const, radius: ['57%','78%'], center: ['50%','44%'], avoidLabelOverlap: true, label: { show: false }, itemStyle: { borderColor: '#fff', borderWidth: 3, borderRadius: 7 }, data: [{ value: mistakeStats.value.mastered, name: '复测掌握', itemStyle: { color: '#7b5add' } }, { value: mistakeStats.value.upcoming, name: '待复测', itemStyle: { color: '#b8a7f1' } }, { value: mistakeStats.value.due, name: '已到期', itemStyle: { color: '#ece9f5' } }] }] }))
const graphOption = computed(() => ({ animationDuration: 550, tooltip: { trigger: 'item' as const, formatter: (p: unknown) => (p as {data:{name:string}}).data.name }, series: [{ type: 'graph' as const, layout: 'force' as const, roam: false, draggable: true, force: { repulsion: 70, edgeLength: 62, gravity: .12 }, label: { show: true, color: '#535064', fontSize: 12 }, lineStyle: { color: '#cec6e9', opacity: .72, width: 1.3 }, data: graphNodes.value.slice(0,9).map((n,i) => ({ id:n.id, name:n.name, symbolSize:i===0?56:i<4?34:25, itemStyle:{ color:i===0?'#7857dc':i<4?'#80d6c7':'#a7a2ec', shadowBlur:i===0?18:6, shadowColor:i===0?'rgba(116,83,220,.28)':'rgba(110,106,180,.16)' }, label:{ show:true, fontWeight:i===0?700:500, fontSize:i===0?12:9 } })), links: graphLinks.value.filter(l => graphNodes.value.slice(0,9).some(n=>n.id===l.source)&&graphNodes.value.slice(0,9).some(n=>n.id===l.target)), emphasis:{ focus:'adjacency' as const, lineStyle:{width:3} } }] }))
const recommendations = computed(() => mistakes.value.filter(item => !item.mastered).sort((a,b) => b.wrong-a.wrong).slice(0,3).map(item => ({course:item.course,title:`复习${item.topic}`,reason:`你记录了 ${item.wrong} 次相关错题`,urgency:'待复习',color:'violet',icon:'复'})))
function openQuiz(topic?: string) { if (topic) localStorage.setItem('studypath.quizTopic', topic); router.push('/quiz') }
</script>

<template>
  <div class="page-content dashboard-page" :class="{'dashboard-unavailable':dashboardError||dashboardLoading}">
    <section class="welcome-row"><div><div class="welcome-kicker"><span class="live-dot"></span>{{ todayLabel }} · 学习概览</div><h1>{{new Date().getHours()<11?'早上好':new Date().getHours()<18?'下午好':'晚上好'}}，{{ profileState.name || '学习者' }} <span class="wave">☀</span></h1><p>让知识有迹可循，让每一次学习更加高效。</p></div><div class="welcome-actions"><button class="btn btn-secondary" @click="router.push('/library')"><FileUp :size="16" />上传资料</button><input ref="uploadInput" type="file" accept=".pdf,.docx,.txt,.md" hidden @change="router.push('/library')" /><button class="btn btn-primary" @click="router.push('/chat')"><Sparkles :size="16" />开始学习<ArrowRight :size="15" /></button></div></section>
    <div v-if="dashboardError" class="dashboard-load-state" role="alert"><span><b>学习数据暂时没有加载完成</b><small>{{ dashboardError }}</small></span><button class="btn btn-secondary btn-compact" @click="router.go(0)">重新加载</button></div>
    <div v-else-if="dashboardLoading" class="dashboard-load-state" role="status"><span><b>正在同步你的学习空间</b><small>正在读取课程、计划与复习记录…</small></span><span class="dashboard-loader" aria-hidden="true"></span></div>
    <section class="stats-grid">
      <article class="stat-card"><div class="stat-icon lilac"><Clock3 :size="19" /></div><div class="stat-label">今日学习时长</div><div class="stat-value">{{ stats.hoursToday }}<small> 小时</small></div><div class="stat-foot"><span class="trend">{{activeStudy?'计时中':'专注计时'}}</span><span>{{activeStudy?studyClock:'按真实计时统计'}}</span></div><button class="timer-control" @click="toggleStudyTimer">{{activeStudy?'结束本次学习':'开始专注计时'}}</button><div class="stat-spark spark-purple"><i v-for="(h,i) in stats.weekHours" :key="i" :style="{height:(h*12)+'px'}"></i></div></article>
      <article class="stat-card"><div class="stat-icon mint"><Layers3 :size="19" /></div><div class="stat-label">间隔复测掌握错题</div><div class="stat-value">{{ stats.mastered }}</div><div class="stat-foot"><span class="trend">账号记录</span><span>通过间隔复测</span></div><div class="stat-ring"><span>{{ stats.mastered }}</span></div></article>
      <article class="stat-card"><div class="stat-icon peach"><Target :size="19" /></div><div class="stat-label">本周学习任务</div><div class="stat-value">{{ store.tasks.filter(task=>task.done).length }}<small> / {{ store.tasks.length }}</small></div><div class="stat-foot"><span class="trend">学习计划</span><span>保持学习节奏</span></div><div class="stat-progress"><i :style="{width:(store.tasks.length?store.tasks.filter(task=>task.done).length/store.tasks.length*100:0)+'%'}"></i></div></article>
      <article class="stat-card"><div class="stat-icon rose"><Flame :size="19" /></div><div class="stat-label">连续测验活跃天数</div><div class="stat-value">{{ stats.streak }}<small> 天</small></div><div class="stat-foot"><span class="trend orange-text">测验记录连续天数</span></div><div class="streak-dots"><i v-for="i in 7" :key="i" :class="{filled:i<=stats.streak}">{{ ['一','二','三','四','五','六','日'][i-1] }}</i></div></article>
    </section>
    <section class="recommendation-banner"><div class="recommend-main"><div class="section-heading light"><div><div class="recommend-eyebrow"><Sparkles :size="13" /> 个性化复习建议</div><h2>根据你的错题记录安排复习</h2><p>建议根据当前账号保存的复测记录生成。</p></div><div class="recommend-badge"><span>●</span> {{ recommendations.length ? '来自账号错题记录' : '暂无待复习记录' }}</div></div><div class="recommend-list"><button v-for="item in recommendations" :key="item.title" class="recommend-item" @click="item.course==='数据结构'?router.push('/graph'):router.push('/path')"><span class="rec-icon" :class="item.color">{{ item.icon }}</span><span class="rec-content"><span class="rec-meta"><b>{{ item.course }}</b><i :class="item.color">{{ item.urgency }}</i></span><strong>{{ item.title }}</strong><small>{{ item.reason }}</small></span><span class="rec-action"><ArrowUpRight :size="16" /></span></button><div v-if="!recommendations.length" class="recommend-empty"><span>目前没有待复习错题</span><small>完成一次测验后，这里会根据账号记录整理复习建议。</small><button @click="router.push('/quiz')">去完成测验 <ArrowRight :size="14" /></button></div></div></div><div class="recommend-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-core"><BookOpen :size="35" /></div><span class="art-orb orb-a">Aa</span><span class="art-orb orb-b"><Network :size="17" /></span><span class="art-orb orb-c"><Lightbulb :size="19" /></span><span class="art-star star-a">✳</span><span class="art-star star-b">✧</span><span class="art-label">专注 · 理解 · 掌握</span></div></section>
    <section class="dashboard-row charts-row"><article class="panel chart-panel"><div class="panel-heading"><div><h3>学习趋势</h3><p>过去 7 天的测验平均正确率</p></div><button class="select-pill" aria-label="查看学习分析" @click="router.push('/analytics')">近 7 天 <ChevronRight :size="13" /></button></div><div class="chart-legend"><i></i>正确率 <span>% / 天</span></div><ChartPanel v-if="hasQuizHistory" :option="learningOption" height="210px" /><div v-else class="analytics-empty">完成一次测验后显示测验正确率趋势</div></article><article class="panel mastery-panel"><div class="panel-heading"><div><h3>错题复测状态</h3><p>依据账号保存的复测记录</p></div><button class="text-link" @click="router.push('/analytics')">详细分析 <ArrowRight :size="13" /></button></div><div class="mastery-chart-wrap"><ChartPanel :option="masteryOption" height="185px" /><div class="mastery-center"><b>{{ mistakeStats.mastered + mistakeStats.upcoming + mistakeStats.due }}</b><span>错题记录</span></div></div><div class="mastery-legend"><span><i class="dot-purple"></i>复测掌握 <b>{{ mistakeStats.mastered }}</b></span><span><i class="dot-lilac"></i>待复测 <b>{{ mistakeStats.upcoming }}</b></span><span><i class="dot-gray"></i>已到期 <b>{{ mistakeStats.due }}</b></span></div></article></section>
    <section class="dashboard-row lower-row"><article class="panel graph-preview"><div class="panel-heading"><div><h3>知识图谱</h3><p>数据结构 · 知识关联一目了然</p></div><button class="text-link" @click="router.push('/graph')">查看完整图谱 <ArrowRight :size="13" /></button></div><div class="graph-preview-canvas"><ChartPanel :option="graphOption" height="238px" /><div class="graph-float-note"><span class="graph-pulse"></span><span><b>数据结构</b><small>{{graphNodes.length}} 个知识点 · 点击探索</small></span><ArrowUpRight :size="14" /></div><button class="graph-open" @click="router.push('/graph')">探索图谱 <ArrowRight :size="13" /></button></div></article><article class="panel continue-panel"><div class="panel-heading"><div><h3>继续学习</h3><p>课程目录已从服务端加载。</p></div><button class="icon-button" @click="router.push('/courses')"><ArrowRight :size="16" /></button></div><div class="continue-list"><button v-for="(course,i) in courses.slice(0,3)" :key="course.id" class="continue-course" @click="router.push('/courses')"><span class="course-monogram" :style="{ '--course-color':course.color }">{{ course.icon }}</span><span class="continue-copy"><span><b>{{ course.name }}</b><small>课程目录</small></span><small>{{ course.chapter }}</small></span><span class="play-circle"><Play :size="13" fill="currentColor" /></span></button></div><button class="all-courses-link" @click="router.push('/courses')">查看全部课程 <ChevronRight :size="14" /></button></article></section>
    <section class="panel task-panel"><div class="panel-heading"><div><h3>近期学习计划</h3><p>把今天的小目标，变成掌握的新知识</p></div><button class="text-link" @click="router.push('/plan')">管理计划 <ArrowRight :size="13" /></button></div><div class="task-table"><div v-for="task in tasks" :key="task.id" class="task-row"><button class="task-check" :class="{checked:task.done}" :aria-label="task.done?'标记未完成':'完成任务'" @click="store.toggleTask(task.id)"><Check v-if="task.done" :size="13" /></button><span class="task-title" :class="{done:task.done}">{{ task.title }}</span><span class="task-course">{{ task.course }}</span><span class="task-date"><Clock3 :size="13" />{{ task.date }}</span><span class="priority-tag" :class="task.priority==='高'?'priority-high':task.priority==='中'?'priority-medium':'priority-low'">{{ task.priority }}优先级</span><button class="task-open" @click="router.push('/plan')"><ChevronRight :size="16" /></button></div><div v-if="!tasks.length" class="task-empty">今天的计划已完成，做得很好！ <span>✦</span></div></div><button class="add-task-button" @click="router.push('/plan')"><Plus :size="14" /> 添加学习任务</button></section>
    <div class="dashboard-footnote"><span><span class="demo-tag">账户学习数据</span> 课程、图谱、测验、错题和计划均由服务端提供并按账号保存。</span><button @click="router.push('/analytics')">查看学习报告 <ArrowRight :size="13" /></button></div>
  </div>
</template>

<style scoped>
.timer-control{position:relative;z-index:1;margin-top:7px;border:1px solid #e8e1f5;background:#faf8ff;color:#7353cb;border-radius:7px;padding:5px 9px;font-size:10px;font-weight:600;cursor:pointer}
.timer-control:hover{background:#f1ebff;border-color:#cfc0f4}
</style>
